import React, { useState, useRef, useEffect } from 'react';
import './CustomerSearch.css';

const CustomerSearch = ({ selectedCustomer, onCustomerSelect }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const [filteredCustomers, setFilteredCustomers] = useState([]);
  const inputRef = useRef(null);

  // 더미 고객 데이터
  const customers = [
    { id: 1, name: 'Walk-in Customer', phone: '', type: 'walk-in' },
    { id: 2, name: 'John Doe', phone: '+60123456789', type: 'member' },
    { id: 3, name: 'Jane Smith', phone: '+60198765432', type: 'member' },
    { id: 4, name: 'Ahmad Rahman', phone: '+60134567890', type: 'member' },
    { id: 5, name: 'Siti Nurhaliza', phone: '+60187654321', type: 'member' },
    { id: 6, name: 'David Tan', phone: '+60156789012', type: 'member' }
  ];

  useEffect(() => {
    if (searchTerm.length >= 1) {
      const filtered = customers.filter(customer =>
        customer.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
        customer.phone.includes(searchTerm)
      );
      setFilteredCustomers(filtered);
      setIsOpen(true);
    } else {
      setFilteredCustomers([customers[0]]);
      setIsOpen(false);
    }
  }, [searchTerm]);

  const handleInputFocus = () => {
    if (searchTerm.length === 0) {
      setFilteredCustomers(customers);
      setIsOpen(true);
    }
  };

  const handleCustomerSelect = (customer) => {
    onCustomerSelect(customer);
    setIsOpen(false);
    setSearchTerm('');
    inputRef.current?.blur();
  };

  const handleInputChange = (e) => {
    const value = e.target.value;
    setSearchTerm(value);
  };

  const handleClearSearch = () => {
    setSearchTerm('');
    setIsOpen(false);
    onCustomerSelect(customers[0]);
  };

  return (
    <div className="customer-search">
      <div className="search-input-container">
        <input
          ref={inputRef}
          type="text"
          className="customer-input"
          placeholder="Type to search customer..."
          value={searchTerm}
          onChange={handleInputChange}
          onFocus={handleInputFocus}
          onBlur={() => setTimeout(() => setIsOpen(false), 200)}
        />
        {searchTerm && (
          <button className="clear-search" onClick={handleClearSearch}>
            ×
          </button>
        )}
        {!searchTerm && (
          <div className="selected-customer">
            {selectedCustomer?.type === 'member' && <span className="member-badge">👤</span>}
            {selectedCustomer?.name}
          </div>
        )}
      </div>

      {isOpen && filteredCustomers.length > 0 && (
        <div className="customer-dropdown">
          {filteredCustomers.map(customer => (
            <div
              key={customer.id}
              className={`customer-option ${customer.type} ${customer.id === selectedCustomer?.id ? 'selected' : ''}`}
              onClick={() => handleCustomerSelect(customer)}
            >
              <div className="customer-name">
                {customer.type === 'member' && <span className="member-badge">👤</span>}
                {customer.name}
              </div>
              {customer.phone && (
                <div className="customer-phone">{customer.phone}</div>
              )}
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

export default CustomerSearch;
